from pathlib import Path
def words(s):
 t=re.sub(r'<(script|style)[\s\S]*?</\1>',' ',s,flags=re.I); t=re.sub(r'<[^>]+>',' ',t); return len(re.findall(r'[\wآ-ی]+',t))
def ul(items): return '<ul>'+''.join('<li>'+escape(x)+'</li>' for x in items)+'</ul>'
def render(b):
 url=BASE+'brands/'+b['slug']+'.html'; schema={'@context':'https://schema.org','@graph':[{'@type':'WebPage','name':'تامین و سورسینگ '+b['fa'],'url':url,'inLanguage':'fa-IR','about':{'@type':'Brand','name':b['name'],'url':b['official']}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'خانه','item':BASE},{'@type':'ListItem','position':2,'name':'برندها','item':BASE+'brands/'},{'@type':'ListItem','position':3,'name':b['name'],'item':url}]}]}
 secs=''.join('<h2>'+escape(h)+'</h2><p>'+escape(t)+'</p>' for h,t in b['sections']); links=''.join('<a href="'+href+'">'+escape(label)+'</a>' for label,href in b['products']); faq=''.join('<div class="box"><b>'+escape(q)+'</b><p>'+escape(a)+'</p></div>' for q,a in b['faq'])
 body=f'''<!doctype html><html lang="fa" dir="rtl"><head><link rel="icon" type="image/png" sizes="32x32" href="../assets/images/favicon/favicon-32.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>تامین و سورسینگ {escape(b['fa'])} | پیشرو تجهیز فرتاک</title><meta name="description" content="{escape(b['desc'][:165])}"><meta name="robots" content="index, follow"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="fa-IR" href="{url}"><link rel="alternate" hreflang="x-default" href="{url}"><meta property="og:title" content="تامین و سورسینگ {escape(b['fa'])}"><meta property="og:description" content="{escape(b['desc'][:165])}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/images/ptf-logo.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="تامین و سورسینگ {escape(b['fa'])}"><meta name="twitter:description" content="{escape(b['desc'][:165])}"><meta name="twitter:image" content="{BASE}assets/images/ptf-logo.png"><link rel="stylesheet" href="../assets/css/style.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False,separators=(',',':'))}</script><style>body{{background:#f8fafc}}.hero{{padding:130px 0 50px;background:#0f2744;color:#fff}}.hero h1{{color:#fff}}.wrap{{display:grid;grid-template-columns:1fr 300px;gap:24px;margin:28px auto}}.card,.side,.box{{background:#fff;border:1px solid #e2e8f0;border-radius:24px;padding:26px}}.card p,.card li,.box p{{line-height:2}}.links a,.side a{{display:block;border:1px solid #e2e8f0;border-radius:14px;padding:10px;margin:8px;text-decoration:none;color:#0f2744}}</style></head><body><header class="site-header scrolled"><div class="container nav-wrap"><a class="brand" href="../"><img width="54" height="54" loading="lazy" src="../assets/images/ptf-logo.png" alt="لوگو"><span><b>پیشرو تجهیز فرتاک</b></span></a><nav class="main-nav"><a href="../">خانه</a><a href="./">برندها</a><a href="../services/products/">محصولات</a><a href="../rfq/">RFQ</a></nav></div></header><section class="hero"><div class="container"><h1>تامین و سورسینگ {escape(b['fa'])}</h1><p>{escape(b['desc'])}</p></div></section><main class="container wrap"><article class="card"><div class="box"><b>تذکر حقوقی:</b><p>این صفحه ادعای نمایندگی رسمی یا موجودی دائمی برند {escape(b['name'])} ندارد و صرفاً راهنمای سورسینگ پروژه‌ای است.</p></div>{secs}<h2>محصولات مرتبط</h2><div class="links">{links}</div><h2>چک‌لیست RFQ</h2>{ul(['Part Number یا Model Code کامل','تعداد و Tag/Service','کشور ساخت یا Origin مجاز','گواهی‌ها و مدارک موردنیاز پروژه','وضعیت New/Original و شرایط گارانتی','Lead Time و امکان تامین Spare Part'])}<h2>پرسش‌های متداول</h2>{faq}<p>در پروژه‌های وندورلیست‌دار، نام برند کافی نیست. مدل دقیق، Revision، مدارک، کشور ساخت و تطبیق با دیتاشیت باید کنترل شود. اگر کالا جایگزین مدل قدیمی است، ابعاد، پروتکل، Function و مدارک باید قبل از خرید تایید شود.</p></article><aside class="side"><a href="../services/products/">هاب محصولات</a><a href="../about/company-profile/">پروفایل رسمی شرکت</a><a href="../rfq/">ثبت RFQ</a><a href="{b['official']}" target="_blank" rel="noopener">وب‌سایت رسمی برند</a></aside></main><script src="../assets/js/ptf-metrics.js" defer></script></body></html>'''
